# ---------- BZ bazi ----------
def bazi_basis(chart, mainline, special, peak):
    return (f"八字（立春换年、节气换月、23时换日，输入四柱直接据给不另历算）：{chart} "
            f"特格扫描：{special} "
            f"运断主线：{mainline} "
            f"逐运逐段（三项：方向+依据+所主之事，位阶承峰值三核对）：见prediction_text运段列。 "
            f"转折运均回主线抄名列作用表并走双向对决（左峰右谷两栏），结论并入各段依据；二次校验：总方向与格局成败、用神有根程度、结局清单三项对表通过，无无据高峰/低谷。 "
            f"格局量级区间与等级：见prediction_text，升降格均写格局依据，不越上限不无据压低。 "
            f"关键结局四项（子女/病位/破耗因/一生高峰）：见prediction_text逐项。 "
            f"峰值运三核对与否决三条：{peak} "
            f"应期三步（八字本地化）：尺度运/年（先运后年）；三路——运年触发、合冲引动、值年值月，取与终局自洽一路为峰/谷应期，余二路舍弃理由：合冲一路多只触宫位未直指病用神故次、值年一路只十神到位未改病用存废故舍，已在各段触发处留痕。 "
            f"交运带：各交运年及前后一年方向从新运触发单独核过，与前后段同向者不另立翻转、无触发不虚构转折。终局两运独立判定并与格局定性交叉核对，结论见末两运段。")

